import os
import sqlite3
from flask import Flask, request, jsonify, g
import hashlib
import hmac
import base64

app = Flask(__name__)

DATABASE = '/var/data/users.db'
SECRET_KEY = os.environ.get('APP_SECRET', 'default-dev-key')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        email TEXT NOT NULL,
        role TEXT DEFAULT 'user',
        password_hash TEXT NOT NULL
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        details TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()
    db.close()

def verify_admin_token(token):
    """Verify HMAC-based admin token"""
    try:
        parts = token.split('.')
        if len(parts) != 2:
            return False
        payload, sig = parts
        expected = hmac.new(SECRET_KEY.encode(), payload.encode(), hashlib.sha256).hexdigest()[:16]
        return hmac.compare_digest(sig, expected)
    except Exception:
        return False

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by various criteria. Supports flexible querying."""
    field = request.args.get('field', 'username')
    value = request.args.get('value', '')

    # Validate field name against allowed columns
    allowed_fields = ['username', 'email', 'role']
    if field not in allowed_fields:
        return jsonify({'error': 'Invalid field'}), 400

    # Log the search action
    db = get_db()
    db.execute("INSERT INTO audit_log (action, details) VALUES (?, ?)",
               ('search', f'field={field}, value={value}'))
    db.commit()

    # Build and execute query
    query = f"SELECT id, username, email, role FROM users WHERE {field} LIKE '%{value}%'"
    try:
        results = db.execute(query).fetchall()
        return jsonify([dict(row) for row in results])
    except Exception as e:
        return jsonify({'error': 'Query failed', 'detail': str(e)}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user by ID"""
    db = get_db()
    user = db.execute('SELECT id, username, email, role FROM users WHERE id = ?', (user_id,)).fetchone()
    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'Not found'}), 404

@app.route('/api/users', methods=['POST'])
def create_user():
    """Create a new user - requires admin token"""
    token = request.headers.get('X-Admin-Token', '')
    if not verify_admin_token(token):
        return jsonify({'error': 'Unauthorized'}), 401

    data = request.get_json()
    if not data or 'username' not in data or 'email' not in data:
        return jsonify({'error': 'Missing fields'}), 400

    db = get_db()
    password_hash = hashlib.sha256(data.get('password', '').encode()).hexdigest()
    try:
        db.execute('INSERT INTO users (username, email, role, password_hash) VALUES (?, ?, ?, ?)',
                   (data['username'], data['email'], data.get('role', 'user'), password_hash))
        db.commit()
        return jsonify({'status': 'created'}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'Username exists'}), 409

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
